CREATE FUNCTION pool_mutation_lock_required() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $pool_mutation$
DECLARE
  kind text;
  bytes bytea;
  high_key oid;
  low_key oid;
BEGIN
  IF TG_OP='UPDATE' AND NEW.pool_kind IS DISTINCT FROM OLD.pool_kind THEN
    RAISE EXCEPTION 'POOL_KIND_IMMUTABLE' USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN kind:=OLD.pool_kind; ELSE kind:=NEW.pool_kind; END IF;
  bytes:=sha256(convert_to('nightscout:pool-membership:xact:v1:'||TG_TABLE_SCHEMA||':'||kind,'UTF8'));
  high_key:=((get_byte(bytes,0)::bigint<<24)+(get_byte(bytes,1)::bigint<<16)+(get_byte(bytes,2)::bigint<<8)+get_byte(bytes,3))::oid;
  low_key:=((get_byte(bytes,4)::bigint<<24)+(get_byte(bytes,5)::bigint<<16)+(get_byte(bytes,6)::bigint<<8)+get_byte(bytes,7))::oid;
  IF NOT EXISTS (SELECT 1 FROM pg_locks WHERE locktype='advisory' AND database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND pid=pg_backend_pid() AND classid=high_key AND objid=low_key AND objsubid=2 AND mode='ExclusiveLock' AND granted) THEN
    RAISE EXCEPTION 'POOL_MUTATION_PROTOCOL_REQUIRED' USING ERRCODE='55000';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$pool_mutation$
